def parse_date(s: str):
    # Try ISO date format (YYYY-MM-DD or YYYY-MM-DDTHH:MM:SS)
    try:
        return datetime.date.fromisoformat(s)
    except ValueError:
        pass

    # Handle ISO datetime: strip time part after T
    if "T" in s:
        date_part = s.split("T")[0]
        try:
            return datetime.date.fromisoformat(date_part)
        except ValueError:
            raise ValueError(f"Invalid date: {s}")

    # Try US MDY format: MM/DD/YYYY
    mdy = re.fullmatch(r"(\d{2})/(\d{2})/(\d{4})", s)
    if mdy:
        month, day, year = int(mdy.group(1)), int(mdy.group(2)), int(mdy.group(3))
        try:
            return datetime.date(year, month, day)
        except ValueError:
            raise ValueError(f"Invalid date: {s}")

    raise ValueError(f"Invalid date: {s}")

